var conditionReportingAgentTypes = map[string]bool{
	"image-generator": true,
}
func senderMayReportConditions(agentType string) bool { return conditionReportingAgentTypes[agentType] }

func parseReportedConditions(normalisedData map[string]interface{}) (conditions []reportedCondition, malformed bool) {
	raw, present := normalisedData["reported_conditions"]
	if !present { return nil, false }              // healthy: one map lookup
	list, ok := raw.([]interface{})
	if !ok { return nil, true }                     // present but not a list — contract broke
	// per-entry extraction as before (skip junk, default severity 'warning', cap 10)
	if len(list) > 0 && len(conditions) == 0 { return nil, true }  // all-junk list = broken too
	return conditions, false
}

func (s *SagaCoordinator) persistReportedConditions(ctx, state, stepName, response, normalisedData) {
	if _, present := normalisedData["reported_conditions"]; !present { return }
	if !senderMayReportConditions(response.Headers.Sender.AgentType) {
		s.logger.Warn("reported_conditions from an UNSANCTIONED sender — not persisted; add the agent type to conditionReportingAgentTypes (with review) if this reporter is intended", ...)
		return
	}
	conditions, malformed := parseReportedConditions(normalisedData)
	if malformed { s.logger.Warn("reported_conditions present but MALFORMED — the reporting contract broke; conditions were lost, fix the emitter", ...); return }
	for _, c := range conditions { entry := s.buildErrorEntry(state, stepName, c.Message); /* sender identity, code, severity, namespaced context */ s.logAgentError(ctx, entry) }
}

